function crateCombinations(weights, target) {
    const sorted = [...weights].sort((a, b) => a - b);
    const results = [];
    for (let mask = 0; mask < (1 << sorted.length); mask++) {
        const chosen = [];
        let sum = 0;
        for (let i = 0; i < sorted.length; i++) {
            if (mask & (1 << i)) {
                chosen.push(sorted[i]);
                sum += sorted[i];
            }
        }
        if (sum === target)
            results.push(chosen);
    }
    return results.sort((a, b) => {
        for (let i = 0; i < Math.min(a.length, b.length); i++)
            if (a[i] !== b[i])
                return a[i] - b[i];
        return a.length - b.length;
    });
}

function crateCombinations(weights, target) {
    const sorted = [...weights].sort((a, b) => a - b);
    const results = [];
    const chosen = [];
    function extend(from, remaining) {
        if (remaining === 0) {
            results.push([...chosen]);
            return;
        }
        for (let i = from; i < sorted.length && sorted[i] <= remaining; i++) {
            chosen.push(sorted[i]);
            extend(i + 1, remaining - sorted[i]);
            chosen.pop();
        }
    }
    extend(0, target);
    return results;
}
